import{z as n,x as i,o as s,c as B,q as o,j as r,D as A,d as e,s as C,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"CSMA/CA 无线对照","description":"","frontmatter":{"title":"CSMA/CA 无线对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csma-ca.md","filePath":"cs/csma-ca.md","lastUpdated":1791063341000}'),d={name:"cs/csma-ca.md"};function p(c,a,m,D,u,S){const E=i("Mermaid");return s(),B("div",null,[a[2]||(a[2]=o('<h1 id="csma-ca-无线对照" tabindex="-1">CSMA/CA 无线对照 <a class="header-anchor" href="#csma-ca-无线对照" aria-label="Permalink to &quot;CSMA/CA 无线对照&quot;">​</a></h1><div class="epigraph"><p>无线往往不能边发边听自己的冲突；改成发前避让，并用预约把隐藏终端的碰撞推开。</p><footer>—— 据 IEEE 802.11；Kurose and Ross 对 CSMA/CA 与隐藏终端的整理</footer></div><p><a href="/cs/csma-switch">上一课</a>在有线共享介质上用 CSMA/CD，又用交换机把冲突域收到端口。本课不重讲 MAC 学习。缺口是无线：同一信道上仍要多址，但发送机自己的信号淹没接收，<strong>冲突检测（CD）做不成</strong>。对照是 CSMA/CA：避让代替边听。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有线 CD 假设：发送时仍能从介质上听出别人的能量。无线收发隔离困难，而且「我听不见你」不等于「目的听不见你」——隐藏终端。若仍按以太网那样抢完再靠 FCS 发现，碰撞浪费整帧空气时间。缺口是访问方法换成<strong>冲突避免</strong>，不是新的 IP。</p><p><span class="marginnote">隐藏终端：A 与 C 都听不见对方，却都能让 B 处碰撞。暴露终端是对偶：听见别人并不等于自己发送会破坏那次接收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CSMA/CA：发前听信道；忙则随机退避。可选 RTS/CTS：短控制帧让周围节点设置 NAV，在一段时间内不发，把信道当预约。确认仍常要显式 ACK，因为单向听到的「能量」不等于对端收对。本课不把 802.11 全部帧类型与速率自适应写成标准正文。</p><p><span class="marginnote">NAV（网络分配向量）可以理解为&quot;别人的预约登记本&quot;：听到 RTS/CTS 后，节点把&quot;信道还要忙多久&quot;记成一个倒计时，期间闭嘴不发。这叫虚拟载波监听——不必真去听空气里的能量，查登记本就够。</span></p>',9)),(s(),r(l,null,{default:A(()=>[C(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LISTEN%5B%22%E5%8F%91%E5%89%8D%E5%90%AC%22%5D%20--%3E%20BACK%5B%22%E5%BF%99%E5%88%99%E9%80%80%E9%81%BF%22%5D%0A%20%20BACK%20--%3E%20RTS%5B%22%E5%8F%AF%E9%80%89%20RTS%2FCTS%20%E9%A2%84%E7%BA%A6%22%5D%0A%20%20RTS%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%E5%B8%A7%22%5D%0A%20%20DATA%20--%3E%20ACK%5B%22%E5%AF%B9%E7%AB%AF%20ACK%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("CA 把碰撞从「发到一半发现」改成「尽量别同时发」。交换机那一套学源 MAC、缩小冲突域，在无线接入点上变成基础结构模式：站点经 AP 转发，但空口仍是共享介质。FCS（"),t("a",{href:"/cs/frame-crc"},"上一课的 CRC"),e("）照旧丢坏帧；避让只降低碰撞概率。端到端可靠性仍不在这一层。")],-1)),(s(),r(l,null,{default:A(()=>[C(E,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22A%20%E5%8F%91%E6%95%B0%E6%8D%AE%E7%BB%99%20B%22%5D%20--%3E%20Q%7B%22%E7%94%A8%20RTS%2FCTS%20%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E7%94%A8%22%7C%20C%5B%22%E9%9A%90%E8%97%8F%E7%BB%88%E7%AB%AF%20C%20%E5%90%8C%E6%97%B6%E5%8F%91%22%5D%0A%20%20C%20--%3E%20X%5B%22%E4%B8%A4%E5%B8%A7%E5%9C%A8%20B%20%E5%A4%84%E7%A2%B0%E6%92%9E%EF%BC%8C%E6%95%B4%E5%B8%A7%E9%87%8D%E4%BC%A0%22%5D%0A%20%20Q%20--%3E%7C%22%E7%94%A8%22%7C%20R%5B%22A%20%E5%85%88%E5%8F%91%E7%9F%AD%20RTS%22%5D%0A%20%20R%20--%3E%20S%5B%22B%20%E5%B9%BF%E6%92%AD%20CTS%22%5D%0A%20%20S%20--%3E%20N%5B%22C%20%E5%90%AC%E8%A7%81%20CTS%EF%BC%8C%E8%AE%BE%20NAV%20%E9%9D%99%E9%BB%98%22%5D%0A%20%20N%20--%3E%20OK%5B%22A%20%E7%8B%AC%E5%8D%A0%E4%BF%A1%E9%81%93%E5%8F%91%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">CD 与 CA 的差别可以类比开会：CD 是边发言边听有没有人和自己撞声，撞了立刻停；CA 是发言前先举手说&quot;我要讲了&quot;，大家听见就闭嘴。无线网卡&quot;边说边听自己&quot;做不到，只好改用举手预约。</span></p><p><span class="marginnote">初学者容易以为&quot;避让就等于不碰撞&quot;。实际上 CA 只是把概率压低——比如两个节点的随机倒计时恰好同时归零，照样撞。真正确认&quot;对方收到了&quot;靠的是 ACK 与重传，避让并不提供可靠性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入蜂窝调度与 TDMA 主干，不把蓝牙跳频当 802.11。全双工有线交换口上已经不用 CA；不要把无线退避抄回数据中心以太网当默认。生成树处理的是有线环路，下一课，不是隐藏终端。</p><p>后课默认：共享空气用避让与预约。有线交换网里广播域仍可能环，下一课生成树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无线难做 CD，CSMA/CA 用听、退避与可选预约。</li><li>隐藏终端是几何问题，不是 CRC 多项式选错。</li><li>有线环路是另一缺口，下一课生成树。</li><li>出处：IEEE 802.11；Kurose and Ross。</li></ul>',7))])}const _=n(d,[["render",p]]);export{h as __pageData,_ as default};
